// 先查两个事实：仓库是否公开、记忆数据体积——这决定提问内容
const size = await tools.pwsh({
  command: `
foreach ($d in @("$env:DSH_HOME\.dsh-memory", "$env:USERPROFILE\.openviking", "$env:DSH_HOME\grill-first", "$env:DSH_HOME\sessions", "$env:DSH_HOME\storages")) {
  if (Test-Path $d) {
    $s = (Get-ChildItem $d -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
    "{0,-45} {1,8:N1} MB  ({2} 文件)" -f $d, ($s/1MB), (Get-ChildItem $d -Recurse -File -ErrorAction SilentlyContinue).Count
  }
}
`,
  description: "统计记忆数据体积"
});
console.log(size.stdout);

const r = await tools.web_fetch({ url: "https://github.com/jjq1993148743/My-second-brain" });
if (r.statusCode === 200) {
  const private = /Page not found|404/i.test(r.body.content);
  console.log("仓库可匿名访问 → ", private ? "否（私有或不存在）" : "是（公开仓库）");
} else {
  console.log("status:", r.statusCode);
}
